import os
import modal

app = modal.App("yanolja-rosetta-server")

image = (
    modal.Image.from_registry("nvidia/cuda:12.4.0-devel-ubuntu22.04", add_python="3.11")
    .pip_install("huggingface_hub")
    .run_commands(
        "CMAKE_ARGS='-DGGML_CUDA=on' pip install --force-reinstall --no-cache-dir llama-cpp-python"
    )
)

@app.cls(image=image, gpu="H100", timeout=600, container_idle_timeout=300)
class TranslationModel:
    def build_model(self):
        from huggingface_hub import hf_hub_download
        hf_hub_download(
            repo_id="mradermacher/YanoljaNEXT-Rosetta-27B-2511-GGUF",
            filename="YanoljaNEXT-Rosetta-27B-2511.Q4_K_M.gguf",
            local_dir="/root/models"
        )

    @modal.enter()
    def load_model(self):
        from llama_cpp import Llama
        self.llm = Llama(
            model_path="/root/models/YanoljaNEXT-Rosetta-27B-2511.Q4_K_M.gguf",
            n_gpu_layers=-1,
            n_ctx=32768,
            verbose=False
        )

    @modal.method()
    def translate(self, text: str, source_lang: str, target_lang: str):
        prompt = f"Translate the following text from {source_lang} to {target_lang}.\n\nSource:\n{text}\n\nTarget:\n"
        output = self.llm(
            prompt,
            max_tokens=4096,
            stop=["Source:", "Target:"],
            echo=False,
            temperature=0.1
        )
        return output["choices"][0]["text"].strip()

    @modal.web_endpoint(method="POST")
    def api(self, data: dict):
        return {
            "translation": self.translate.local(
                data["text"], 
                data.get("source_lang", "English"), 
                data.get("target_lang", "Hungarian")
            )
        }


