import modal

def main():
    TranslationModel = modal.Cls.lookup("yanolja-rosetta-server", "TranslationModel")
    service = TranslationModel()

    text_to_translate = """
    {
        "menu": {
            "id": "file",
            "value": "File",
            "popup": {
                "menuitem": [
                    {"value": "New", "onclick": "CreateNewDoc()"},
                    {"value": "Open", "onclick": "OpenDoc()"},
                    {"value": "Close", "onclick": "CloseDoc()"}
                ]
            }
        }
    }
    """

    print("Sending request to Modal...")

    result = service.translate.remote(
        text=text_to_translate,
        source_lang="English",
        target_lang="Hungarian"
    )

    print(result)

if __name__ == "__main__":
    main()
